import os, csv

root = 'loglar'
rows = []
for dirpath, dirnames, filenames in os.walk(root):
    for fn in filenames:
        if not fn.endswith('.log'):
            continue
        full = os.path.join(dirpath, fn)
        rel = os.path.relpath(full, root).replace('\\', '/')
        error = warn = info = 0
        try:
            with open(full, 'r', encoding='utf-8', errors='ignore') as f:
                for line in f:
                    line = line.rstrip('\n')
                    if not line.strip():
                        continue
                    parts = line.split()
                    if len(parts) < 3:
                        continue
                    seviye = parts[2]
                    if seviye == 'ERROR':
                        error += 1
                    elif seviye == 'WARN':
                        warn += 1
                    elif seviye == 'INFO':
                        info += 1
        except Exception as e:
            print('Hata:', rel, e)
        rows.append((rel, error, warn, info))

rows.sort(key=lambda r: (-r[1], r[0]))

with open('rapor.csv', 'w', encoding='utf-8', newline='') as f:
    w = csv.writer(f)
    w.writerow(['dosya', 'error', 'warn', 'info'])
    w.writerows(rows)

print('Tamam. Satır sayısı:', len(rows))
for r in rows:
    print(r)
